let filter='All';
function renderApps(){const term=$('search').value.toLowerCase();const found=apps.filter(a=>(filter==='All'||a.category===filter)&&(`${a.name} ${a.desc} ${a.keys.map(k=>examples[k].goal).join(' ')}`).toLowerCase().includes(term));$('app-grid').replaceChildren();found.forEach(a=>{const card=document.createElement('button');card.className='app-card';card.innerHTML=`<div class="app-pair"><span class="ac-icon" aria-hidden="true">»</span><span class="plus">+</span><span class="app-icon" style="background:${a.bg};color:${a.color}" aria-hidden="true">${a.icon}</span><h3>${a.name}</h3></div><p>${a.desc}</p><div class="card-bottom"><span>${a.keys.length} workflow${a.keys.length>1?'s':''} to explore</span><b aria-hidden="true">↗</b></div>`;card.addEventListener('click',()=>openApp(a));$('app-grid').append(card)});if(!found.length){const msg=document.createElement('p');msg.className='empty-search';msg.textContent='No matching apps. Try another search or describe your own idea above.';$('app-grid').append(msg)}$('results-count').textContent=`Showing ${found.length} of ${apps.length} apps`}
function openApp(a){$('workflow-mode').value='reviewed';$('workflow-mode').dispatchEvent(new Event('change'));document.querySelectorAll('.example').forEach(b=>b.hidden=!a.keys.includes(b.dataset.example));$('builder-title').textContent=a.name+' + ActiveCampaign';if(a.keys.length===1)applyExample(a.keys[0]);$('builder').showModal();$('builder').scrollTop=0}
function quick(key){openApp(apps.find(a=>a.keys.includes(key)));applyExample(key)}
$('search').addEventListener('input',renderApps);document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{filter=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',x===b?'true':'false')});renderApps()}));
document.querySelectorAll('[data-quick]').forEach(b=>b.addEventListener('click',()=>quick(b.dataset.quick)));
